@startuml

class Well {
  + code : string
}

abstract class OnshoreWell extends Well {
  + surfaceExtension : float
}

abstract class OffshoreWell extends Well {
  + yearOfInstallation : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantity : float
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class OnshoreWell {
  + pollutionRate() : float
}

class OffshoreWell {
  + geographicalArea : GeographicalArea
  + pollutionRate() : float
}

Well "*" -- "*" Company : extracts
(Well, Company) -- "1" Extraction

@enduml

